pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testRegression_property() public {
        c.XBornID();
        uint256 initialDistributed = c.totalDistributed();
        c.burn(1);
        uint256 expectedRef = initialDistributed - 1;
        uint256 got = c.totalDistributed();
        assertTrue(got == expectedRef, "totalDistributed should have decreased by 1");
    }
}
